fn sum_range_contract(start: Int, end: Int) -> Int
  requires: start <= end;
{
  var sum = 0;
  for i in start..=end { sum = sum + i; }
  return sum;
}

fn sum_range_nocontract(start: Int, end: Int) -> Int {
  var sum = 0;
  for i in start..=end { sum = sum + i; }
  return sum;
}

fn main() -> Int {
  // The contract version has negligible overhead for this loop-heavy function
  // Contract check: one comparison (nanoseconds)
  // Loop body: N iterations (microseconds)
  // Conclusion: keep the contract!
  let r1 = sum_range_contract(1, 100000);
  return r1;
}
